    "easyExplanation": "-아 / 어도 돼요\n\n(-a / eo-do dwae-yo)\n\nmeans\n\nCan I...?\n\nor\n\nIs it OK to...?\n\nUse it when asking someone for permission politely.\n\nNative Koreans use this grammar every day.",
